function validate([root]) {
  if (!Array.isArray(root)) return 'root must be a level-order list.';
  if (root.length === 0) return null;
  if (root[0] === null) return 'Use [] for an empty tree.';
  let count = 0, deepest = 0, next = 1;
  const depths = [1];
  for (let q = 0; q < depths.length; q++) {
    count++;
    deepest = Math.max(deepest, depths[q]);
    for (let side = 0; side < 2 && next < root.length; side++, next++) {
      if (root[next] !== null) depths.push(depths[q] + 1);
    }
  }
  if (next < root.length) return 'Some values have no parent node.';
  if (count > 10000) return 'The tree has at most 10^4 nodes.';
  if (deepest > 1000) return 'The tree is at most 1000 levels deep.';
  if (root.some(v => v !== null && (!Number.isInteger(v) || v < -1000 || v > 1000))) return 'Each node value is an integer between -1000 and 1000.';
  return null;
}

