function longestUnivaluePath(root) {
  // Treat the tree as an undirected graph and run a BFS from every node over equal-valued neighbours.
  if (!root) return 0;
  const nodes = [], parent = new Map([[root, null]]);
  const stack = [root];
  while (stack.length) {
    const node = stack.pop();
    nodes.push(node);
    for (const child of [node.left, node.right]) if (child) { parent.set(child, node); stack.push(child); }
  }
  let answer = 0;
  for (const start of nodes) {
    const dist = new Map([[start, 0]]);
    const queue = [start];
    for (let q = 0; q < queue.length; q++) {
      const node = queue[q];
      answer = Math.max(answer, dist.get(node));
      for (const next of [node.left, node.right, parent.get(node)]) {
        if (next && next.val === start.val && !dist.has(next)) { dist.set(next, dist.get(node) + 1); queue.push(next); }
      }
    }
  }
  return answer;
}

