function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 900 + Math.floor(rand() * 90) : Math.floor(rand() * 13);
  if (n === 0) return [[]];
  const mode = rand();
  const nodes = [{ val: 0, left: null, right: null, depth: 1, parent: -1 }];
  let slots = [[0, 'left'], [0, 'right']];
  // Mode below 0.25 builds a chain that zig-zags downward; otherwise children attach to random free slots,
  // with a bias that sometimes favours the newest slots to grow long branches.
  const bias = rand();
  for (let i = 1; i < n; i++) {
    let pick;
    if (mode < 0.25) pick = slots.length - 1 - Math.floor(rand() * Math.min(2, slots.length));
    else pick = rand() < bias ? slots.length - 1 - Math.floor(rand() * Math.min(2, slots.length)) : Math.floor(rand() * slots.length);
    const [p, side] = slots[pick];
    slots[pick] = slots[slots.length - 1];
    slots.pop();
    nodes[p][side] = i;
    nodes.push({ val: 0, left: null, right: null, depth: nodes[p].depth + 1, parent: p });
    if (nodes[i].depth < 1000) slots.push([i, 'left'], [i, 'right']);
    if (mode < 0.25) slots = slots.filter(([q]) => q === i);
  }
  // Each node copies its parent's value with probability keep, otherwise it takes a fresh value.
  const keep = mode < 0.25 ? 0.97 : 0.3 + rand() * 0.6;
  const span = large ? 1000 : 2;
  const fresh = () => Math.floor(rand() * (2 * span + 1)) - span;
  for (let i = 0; i < n; i++) {
    const node = nodes[i];
    node.val = node.parent >= 0 && rand() < keep ? nodes[node.parent].val : fresh();
  }
  const out = [], queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out];
}
